import {resumeDisciplina} from './informe-disciplina.mjs';
/** Diferencia entre los puntos publicados y 3×G+E. null si falta algún dato: desconocido no es 0. */
export function ajustePuntos(fila){
 const v=[fila?.puntos,fila?.ganados,fila?.empatados];
 if(v.some(x=>x==null||x===''||!Number.isFinite(Number(x))))return null;
 return Number(fila.puntos)-(3*Number(fila.ganados)+Number(fila.empatados));
}
